      { t: "Báo Sài Gòn Giải Phóng — Nhã nhạc, tài sản vô giá của nhân loại (2018)", u: "https://www.sggp.org.vn/nha-nhac-tai-san-vo-gia-cua-nhan-loai-post466894.html", s: "Báo Sài Gòn Giải Phóng" },
      { t: "Wikipedia — Kèn bầu", u: "https://en.wikipedia.org/wiki/K%C3%A8n_b%E1%BA%A7u", s: "Wikipedia" }
